'use strict';

const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

let idx = 0;
const N = data[idx++];
const K = data[idx++];
const T = data[idx++];

const plates = data.slice(idx, idx + N);
idx += N;

const initial = [];
for (let i = 0; i < N; i++) {
  if (data[idx++] === 1) initial.push(i + 1);
}

const maxScore = 9 * K;
const INF = 1e9;
const dp = Array.from({ length: K + 1 }, () => {
  const row = new Int32Array(maxScore + 1);
  row.fill(INF);
  return row;
});
const highestReachable = new Int32Array(K + 1);
highestReachable.fill(-1);

dp[0][0] = 0;
highestReachable[0] = 0;

for (let pos = 1; pos <= N; pos++) {
  const reward = plates[pos - 1];
  const maxChosen = Math.min(pos, K);

  for (let count = maxChosen; count >= 1; count--) {
    const source = dp[count - 1];
    const target = dp[count];
    const sourceMax = highestReachable[count - 1];
    if (sourceMax < 0) continue;

    const moveCost = Math.abs(initial[count - 1] - pos);
    for (let score = 0; score <= sourceMax; score++) {
      const cost = source[score];
      if (cost === INF || cost + moveCost > T) continue;

      const newScore = score + reward;
      const newCost = cost + moveCost;
      if (newCost < target[newScore]) target[newScore] = newCost;
      if (newScore > highestReachable[count]) {
        highestReachable[count] = newScore;
      }
    }
  }
}

console.log(highestReachable[K]);
